const changeSchema = z.enum(["added", "modified", "removed", "renamed"]);
const fieldSchema = z.object({
  name: z.string(),
  type: z.string().optional(),
  pk: z.boolean().optional(),
  fk: z.string().optional(),
  nullable: z.boolean().optional(),
  default: z.string().optional(),
  note: z.string().optional(),
  change: changeSchema.optional(),
  was: z.string().optional(),
});
const relationSchema = z.object({
  from: z.string(),
  to: z.string(),
  kind: z.enum(["1-1", "1-n", "n-n"]).optional(),
  label: z.string().optional(),
});

operations.exampleCall:
erd.addEntity({
  entity: {
    id: "prompt_revisions",
    fields: [{ id: "hash", type: "text", keys: ["pk"] }],
  },
})

erd.addField({
  entity: "pi_agent_sessions",
  field: { id: "prompt_hash", type: "text", nullable: true },
})

erd.addRelationship({
  relationship: {
    id: "sessions-prompt",
    from: { entity: "pi_agent_sessions", fields: ["prompt_hash"] },
    to: { entity: "prompt_revisions", fields: ["hash"] },
    kind: "logical",
  },
})
